import{_ as i,o as n,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"UGSo Spezial","description":"Animierte SVG-Linien und Summenknoten für ioBroker VIS 2.","frontmatter":{"title":"UGSo Spezial","description":"Animierte SVG-Linien und Summenknoten für ioBroker VIS 2."},"headers":[],"relativePath":"iobroker/widgets/ugso-spezial/index.md","filePath":"iobroker/widgets/ugso-spezial/index.md","lastUpdated":1793818143000}'),a={name:"iobroker/widgets/ugso-spezial/index.md"};function s(o,e,d,l,u,g){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ugso-spezial" tabindex="-1">UGSo Spezial <a class="header-anchor" href="#ugso-spezial" aria-label="Permalink to &quot;UGSo Spezial&quot;">​</a></h1><p>Mit <strong>UGSo Spezial</strong> stellst du Datenflüsse in VIS 2 dar, zum Beispiel die Leistung mehrerer Verbraucher. Das Widget-Set enthält zwei Bausteine.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><ul><li><strong>SVG-Line</strong> verbindet Punkte gerade, rechtwinklig oder über Zwischenpunkte. Farben, Strichlängen und Pfeilspitzen sind einstellbar. Positive Werte animieren vorwärts, negative rückwärts; bei null stoppt die Animation. Die Geschwindigkeit kann fest oder vom Betrag des Werts abhängig sein.</li><li><strong>SVG LineBox</strong> addiert bis zu vier Eingangsleitungen und einen optionalen Korrekturwert. Die Summe kann an bis zu zwei Ausgangsleitungen weitergegeben oder in der Laufzeitansicht in einen vorhandenen beschreibbaren numerischen Datenpunkt unter <code>0_userdata.0</code> geschrieben werden. Fehlt der Wert eines ausgewählten Eingangs, wartet die Box auf diesen Wert.</li></ul><p>Im Editor rasten gelbe Endpunkte beim Ziehen an einer anderen Linie oder LineBox ein. Ein Ende mit Pfeilspitze kann nicht andocken. Das Andocken richtet die Grafik aus; die Werteverbindungen stellst du separat in der LineBox ein.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Voraussetzung ist eine laufende VIS-2-Installation. Installiere das Widget-Set über die GitHub-URL des Projekts in ioBroker Admin (Expertenmodus). Starte VIS 2 nach Updates neu, damit die neue Version geladen wird. Im Editor findest du beide Widgets in der Palette unter <strong>UGSo Spezial</strong>.</p><ul><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-spezial" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-spezial/releases" target="_blank" rel="noreferrer">Releases</a></li><li><a href="https://www.npmjs.com/package/iobroker.vis-2-widgets-ugso-spezial" target="_blank" rel="noreferrer">npm</a></li></ul>',8)])])}const c=i(a,[["render",s]]);export{h as __pageData,c as default};
